function mouse_move_2d7d2d4f1b37c81bc50068269ebbf718705cf3fbf56c91bb12aed9ffef5ee9ef97d6de744ab512c448867e417948bac85ffdd5b8d8a7fe32ddc5b98a88e66527(evt) {
    if (evt.buttons > 0) {
          var root = document.getElementById('2d7d2d4f1b37c81bc50068269ebbf718705cf3fbf56c91bb12aed9ffef5ee9ef97d6de744ab512c448867e417948bac85ffdd5b8d8a7fe32ddc5b98a88e66527');
